static std::atomic<unsigned> allocations{0};
void* operator new(std::size_t size) { allocations.fetch_add(1); if(void* p=std::malloc(size?size:1))return p; throw std::bad_alloc(); }
void* operator new[](std::size_t size) { return ::operator new(size); }
// alloc_policy uses nothrow new. Replace that family too: ASan's default
// nothrow allocator bypasses the counting replacements above, and mixing it
// with the fixture's free-based delete is itself an allocator mismatch.
void* operator new(std::size_t size,const std::nothrow_t&) noexcept {allocations.fetch_add(1);return std::malloc(size?size:1);}
void* operator new[](std::size_t size,const std::nothrow_t& tag) noexcept {return ::operator new(size,tag);}
void operator delete(void* p,const std::nothrow_t&) noexcept {std::free(p);}
void operator delete[](void* p,const std::nothrow_t&) noexcept {std::free(p);}

void operator delete(void* p) noexcept {std::free(p);} void operator delete[](void* p) noexcept {std::free(p);}
void operator delete(void* p,std::size_t) noexcept {std::free(p);} void operator delete[](void* p,std::size_t) noexcept {std::free(p);}
using namespace groove;
struct Result { std::vector<float> audio; std::vector<EngineEvent> events; std::vector<MidiEvent> midi; };
static Result run(Engine& engine,unsigned frames,unsigned chunk=128) {
 Result result; result.audio.resize(size_t(frames)*2);
 for(unsigned offset=0;offset<frames;) {
  unsigned count=frames-offset<chunk?frames-offset:chunk;
  unsigned before=allocations.load(); engine.render(result.audio.data()+offset*2,count); assert(allocations.load()==before);
  for(unsigned i=offset*2;i<(offset+count)*2;++i) assert(std::isfinite(result.audio[i]) && std::fabs(result.audio[i])<=1);
  EngineEvent event; while(engine.pop_event(event))result.events.push_back(event);
  MidiEvent midi; while(engine.pop_midi(midi))result.midi.push_back(midi);
  ClockEvent clock; while(engine.pop_clock(clock)){} offset+=count;
 }
 return result;
}
static float peak(const std::vector<float>& audio) { float p=0;for(float x:audio)if(std::fabs(x)>p)p=std::fabs(x);return p; }
static std::vector<uint64_t> notes(const Result& r,unsigned track) {std::vector<uint64_t> samples;for(const auto& event:r.events)if(event.type==EngineEventType::Note && event.track==track)samples.push_back(event.sample);return samples;}
